solutionCodeJson.code:
export type Status = 'PENDING' | 'CONFIRMED' | 'CANCELLED';

// Exclude the cancelled state — a union derived from Status.
export type Active = Exclude<Status, 'CANCELLED'>;

import type { Active } from '../src/active.ts';
const a: Active = 'PENDING';
const b: Active = 'CONFIRMED';
export { a, b };

import type { Active } from '../src/active.ts';
const gone: Active = 'CANCELLED'; // expect TS2322
export { gone };

